-- V69 CPF Enterprise Cache / Async File Job (Oracle)
CREATE TABLE cpf_cache_invalidation_event (
    event_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_key VARCHAR2(100 CHAR) NOT NULL UNIQUE,
    tenant_id VARCHAR2(80 CHAR) NOT NULL,
    namespace_cd VARCHAR2(80 CHAR) NOT NULL,
    cache_key VARCHAR2(512 CHAR) DEFAULT '' NOT NULL,
    event_version NUMBER(19) DEFAULT 0 NOT NULL,
    reason VARCHAR2(500 CHAR) NOT NULL,
    requested_by VARCHAR2(100 CHAR) NOT NULL,
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE INDEX ix_cpf_cache_inv_scope ON cpf_cache_invalidation_event(tenant_id, namespace_cd, event_id);

CREATE TABLE cpf_cache_invalidation_checkpoint (
    consumer_id VARCHAR2(120 CHAR) PRIMARY KEY,
    last_event_id NUMBER(19) DEFAULT 0 NOT NULL,
    updated_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE adm_file_job (
    job_id VARCHAR2(36 CHAR) PRIMARY KEY,
    operation_id VARCHAR2(100 CHAR) NOT NULL UNIQUE,
    request_hash VARCHAR2(64 CHAR) NOT NULL,
    job_type VARCHAR2(20 CHAR) NOT NULL,
    template_code VARCHAR2(100 CHAR) NOT NULL,
    template_version NUMBER(10) NOT NULL,
    file_format VARCHAR2(10 CHAR) NOT NULL,
    job_state VARCHAR2(30 CHAR) NOT NULL,
    dry_run CHAR(1 CHAR) NOT NULL,
    rollback_supported CHAR(1 CHAR) NOT NULL,
    source_path VARCHAR2(1000 CHAR), result_path VARCHAR2(1000 CHAR),
    source_sha256 VARCHAR2(64 CHAR), result_sha256 VARCHAR2(64 CHAR),
    total_rows NUMBER(19) DEFAULT 0 NOT NULL, success_rows NUMBER(19) DEFAULT 0 NOT NULL, failed_rows NUMBER(19) DEFAULT 0 NOT NULL,
    lease_owner VARCHAR2(100 CHAR), fencing_token NUMBER(19) DEFAULT 0 NOT NULL, lease_until TIMESTAMP(6),
    retention_until TIMESTAMP(6) NOT NULL,
    requested_by VARCHAR2(100 CHAR) NOT NULL, reason VARCHAR2(500 CHAR) NOT NULL, client_ip VARCHAR2(64 CHAR),
    error_code VARCHAR2(80 CHAR), error_message VARCHAR2(1000 CHAR),
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE INDEX ix_adm_file_job_claim ON adm_file_job(job_state, lease_until, created_at);
CREATE INDEX ix_adm_file_job_retention ON adm_file_job(retention_until, job_state);

CREATE TABLE adm_file_job_row (
    job_id VARCHAR2(36 CHAR) NOT NULL,
    row_no NUMBER(19) NOT NULL,
    row_state VARCHAR2(30 CHAR) NOT NULL,
    business_key VARCHAR2(200 CHAR),
    payload_json CLOB NOT NULL,
    error_code VARCHAR2(80 CHAR), error_message VARCHAR2(1000 CHAR), rollback_token VARCHAR2(1000 CHAR),
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_adm_file_job_row PRIMARY KEY(job_id,row_no),
    CONSTRAINT fk_adm_file_job_row_job FOREIGN KEY(job_id) REFERENCES adm_file_job(job_id)
);

MERGE INTO adm_menu t USING (SELECT 'FILE_JOB' MENU_ID, '대량파일 Job' MENU_NAME, '/adm#file-jobs' MENU_PATH FROM dual) s
ON (t.MENU_ID=s.MENU_ID) WHEN MATCHED THEN UPDATE SET t.MENU_NAME=s.MENU_NAME,t.MENU_PATH=s.MENU_PATH,t.USE_YN='Y',t.updated_by='SYSTEM',t.updated_at=CURRENT_TIMESTAMP
WHEN NOT MATCHED THEN INSERT(MENU_ID,PARENT_MENU_ID,MENU_NAME,MENU_PATH,SORT_ORDER,USE_YN,created_by,updated_by)
VALUES(s.MENU_ID,NULL,s.MENU_NAME,s.MENU_PATH,61,'Y','SYSTEM','SYSTEM');

DECLARE
  PROCEDURE upsert_button(p_id VARCHAR2,p_menu VARCHAR2,p_action VARCHAR2,p_name VARCHAR2,p_method VARCHAR2,p_path VARCHAR2,p_sort NUMBER) IS
  BEGIN
    MERGE INTO adm_button t USING (SELECT p_id BUTTON_ID FROM dual) s ON (t.BUTTON_ID=s.BUTTON_ID)
    WHEN MATCHED THEN UPDATE SET t.MENU_ID=p_menu,t.ACTION_CODE=p_action,t.BUTTON_NAME=p_name,t.HTTP_METHOD=p_method,t.API_PATTERN=p_path,t.USE_YN='Y',t.updated_by='SYSTEM',t.updated_at=CURRENT_TIMESTAMP
    WHEN NOT MATCHED THEN INSERT(BUTTON_ID,MENU_ID,ACTION_CODE,BUTTON_NAME,HTTP_METHOD,API_PATTERN,SORT_ORDER,USE_YN,created_by,updated_by)
      VALUES(p_id,p_menu,p_action,p_name,p_method,p_path,p_sort,'Y','SYSTEM','SYSTEM');
  END;
BEGIN
  upsert_button('FILE_JOB_READ','FILE_JOB','READ','File Job 조회','GET','/adm/api/file-jobs/**',10);
  upsert_button('FILE_JOB_UPLOAD','FILE_JOB','UPLOAD','Upload 접수','POST','/adm/api/file-jobs/uploads',20);
  upsert_button('FILE_JOB_APPLY','FILE_JOB','APPLY','검증 Job 적용','POST','/adm/api/file-jobs/*/apply',30);
  upsert_button('FILE_JOB_RETRY','FILE_JOB','RETRY','File Job 재시도','POST','/adm/api/file-jobs/*/retry',40);
  upsert_button('FILE_JOB_CANCEL','FILE_JOB','CANCEL','File Job 취소','POST','/adm/api/file-jobs/*/cancel',50);
  upsert_button('FILE_JOB_ROLLBACK','FILE_JOB','ROLLBACK','File Job Rollback','POST','/adm/api/file-jobs/*/rollback',60);
  upsert_button('FILE_JOB_DOWNLOAD','FILE_JOB','DOWNLOAD','Artifact 다운로드','GET','/adm/api/file-jobs/*/artifact',70);
  upsert_button('CACHE_EVICT_KEY','CACHE','EVICT_KEY','단일 Cache 제거','POST','/adm/api/cache/evict-key',30);
  upsert_button('CACHE_EVICT_NAMESPACE','CACHE','EVICT_NAMESPACE','Namespace Cache 제거','POST','/adm/api/cache/evict-namespace',40);
  upsert_button('CACHE_RECONCILE','CACHE','RECONCILE','Cache Durable 재조정','POST','/adm/api/cache/reconcile',50);
END;
/

MERGE INTO adm_role_menu t USING (
 SELECT ROLE_ID,'FILE_JOB' MENU_ID,'Y' READ_YN,
 CASE WHEN ROLE_ID IN ('ADM_ADMIN','ADM_DEV_OPERATOR','ADM_OPERATOR','ADM_BIZ_OPERATOR') THEN 'Y' ELSE 'N' END WRITE_YN
 FROM adm_role WHERE ROLE_ID IN ('ADM_ADMIN','ADM_DEV_OPERATOR','ADM_OPERATOR','ADM_BIZ_OPERATOR','ADM_VIEWER')) s
ON (t.ROLE_ID=s.ROLE_ID AND t.MENU_ID=s.MENU_ID)
WHEN MATCHED THEN UPDATE SET t.READ_YN=s.READ_YN,t.WRITE_YN=s.WRITE_YN,t.updated_by='SYSTEM',t.updated_at=CURRENT_TIMESTAMP
WHEN NOT MATCHED THEN INSERT(ROLE_ID,MENU_ID,READ_YN,WRITE_YN,DELETE_YN,created_by,updated_by)
VALUES(s.ROLE_ID,s.MENU_ID,s.READ_YN,s.WRITE_YN,'N','SYSTEM','SYSTEM');

MERGE INTO adm_role_button t USING (
 SELECT r.ROLE_ID,b.BUTTON_ID,CASE WHEN r.ROLE_ID='ADM_ADMIN' THEN 'Y'
 WHEN r.ROLE_ID IN ('ADM_DEV_OPERATOR','ADM_OPERATOR') AND b.BUTTON_ID NOT IN ('FILE_JOB_ROLLBACK','CACHE_EVICT_NAMESPACE') THEN 'Y'
 WHEN r.ROLE_ID='ADM_BIZ_OPERATOR' AND b.BUTTON_ID IN ('FILE_JOB_READ','FILE_JOB_UPLOAD','FILE_JOB_APPLY','FILE_JOB_DOWNLOAD') THEN 'Y'
 WHEN r.ROLE_ID='ADM_VIEWER' AND b.BUTTON_ID='FILE_JOB_READ' THEN 'Y' ELSE 'N' END ALLOW_YN
 FROM adm_role r JOIN adm_button b ON (b.BUTTON_ID LIKE 'FILE_JOB_%' OR b.BUTTON_ID LIKE 'CACHE_EVICT_%' OR b.BUTTON_ID='CACHE_RECONCILE')
 WHERE r.ROLE_ID IN ('ADM_ADMIN','ADM_DEV_OPERATOR','ADM_OPERATOR','ADM_BIZ_OPERATOR','ADM_VIEWER')) s
ON (t.ROLE_ID=s.ROLE_ID AND t.BUTTON_ID=s.BUTTON_ID)
WHEN MATCHED THEN UPDATE SET t.ALLOW_YN=s.ALLOW_YN,t.updated_by='SYSTEM',t.updated_at=CURRENT_TIMESTAMP
WHEN NOT MATCHED THEN INSERT(ROLE_ID,BUTTON_ID,ALLOW_YN,created_by,updated_by) VALUES(s.ROLE_ID,s.BUTTON_ID,s.ALLOW_YN,'SYSTEM','SYSTEM');

MERGE INTO adm_api_permission t USING (
 SELECT 'API_'||BUTTON_ID API_PERMISSION_ID,MENU_ID API_GROUP_CODE,HTTP_METHOD,API_PATTERN API_PATH,BUTTON_NAME API_NAME,ACTION_CODE PERMISSION_CODE,MENU_ID,BUTTON_ID
 FROM adm_button WHERE BUTTON_ID LIKE 'FILE_JOB_%' OR BUTTON_ID LIKE 'CACHE_EVICT_%' OR BUTTON_ID='CACHE_RECONCILE') s
ON (t.API_PERMISSION_ID=s.API_PERMISSION_ID)
WHEN MATCHED THEN UPDATE SET t.API_PATH=s.API_PATH,t.API_NAME=s.API_NAME,t.PERMISSION_CODE=s.PERMISSION_CODE,t.BUTTON_ID=s.BUTTON_ID,t.USE_YN='Y',t.updated_by='SYSTEM',t.updated_at=CURRENT_TIMESTAMP
WHEN NOT MATCHED THEN INSERT(API_PERMISSION_ID,API_GROUP_CODE,HTTP_METHOD,API_PATH,API_NAME,PERMISSION_CODE,MENU_ID,BUTTON_ID,USE_YN,created_by,updated_by)
VALUES(s.API_PERMISSION_ID,s.API_GROUP_CODE,s.HTTP_METHOD,s.API_PATH,s.API_NAME,s.PERMISSION_CODE,s.MENU_ID,s.BUTTON_ID,'Y','SYSTEM','SYSTEM');

MERGE INTO adm_role_api_permission t USING (
 SELECT rb.ROLE_ID,ap.API_PERMISSION_ID,rb.ALLOW_YN FROM adm_role_button rb JOIN adm_api_permission ap ON ap.BUTTON_ID=rb.BUTTON_ID
 WHERE rb.BUTTON_ID LIKE 'FILE_JOB_%' OR rb.BUTTON_ID LIKE 'CACHE_EVICT_%' OR rb.BUTTON_ID='CACHE_RECONCILE') s
ON (t.ROLE_ID=s.ROLE_ID AND t.API_PERMISSION_ID=s.API_PERMISSION_ID)
WHEN MATCHED THEN UPDATE SET t.ALLOW_YN=s.ALLOW_YN,t.updated_by='SYSTEM',t.updated_at=CURRENT_TIMESTAMP
WHEN NOT MATCHED THEN INSERT(ROLE_ID,API_PERMISSION_ID,ALLOW_YN,created_by,updated_by) VALUES(s.ROLE_ID,s.API_PERMISSION_ID,s.ALLOW_YN,'SYSTEM','SYSTEM');
